import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
g=P*(y-0.547*P*np.log(P)-0.648*t)
one=np.ones_like(t)
best=[]
for w in np.linspace(0.05,2,800):
    for extra in ['none','exp','log','t2']:
        cols=[one,np.sin(w*t),np.cos(w*t)]
        if extra=='exp': cols.append(np.exp(-t))
        if extra=='log': cols.append(np.log(t))
        if extra=='t2': cols+= [t,t**2]
        X=np.column_stack(cols)
        c,_,_,_=np.linalg.lstsq(X,g,rcond=None)
        best.append((np.mean((X@c-g)**2)/np.var(g),w,extra,np.round(c,4)))
best.sort(key=lambda z:z[0])
for b in best[:6]: print(b)

